package db

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"time"

	"github.com/golang-migrate/migrate/v4"
	"github.com/golang-migrate/migrate/v4/database/sqlite"
	"github.com/golang-migrate/migrate/v4/source/iofs"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

// runMigrations applies pending golang-migrate files (generated by
// ent/migrate/main.go) to db. Versioned migration state is tracked in the
// schema_migrations table that golang-migrate manages.
// Reports what it did, on both sides: a slow migration on a large database
// (a WAL checkpoint stalling behind a busy disk) was indistinguishable from a
// hung boot, since nothing said migrations had started, finished, or moved the
// schema version at all.
//
// snapshot, when non-nil, runs after the version is read and before anything
// is applied, only when there is something to apply to a database that already
// holds a schema; an error from it aborts the run with nothing applied.
func runMigrations(
	ctx context.Context,
	db *sql.DB,
	snapshot func(ctx context.Context, from uint) error,
) error {
	src, err := iofs.New(migrationsFS, "migrations")
	if err != nil {
		return fmt.Errorf("migration source: %w", err)
	}
	drv, err := sqlite.WithInstance(db, &sqlite.Config{})
	if err != nil {
		return fmt.Errorf("migration driver: %w", err)
	}
	m, err := migrate.NewWithInstance("iofs", src, "sqlite", drv)
	if err != nil {
		return fmt.Errorf("migrate init: %w", err)
	}

	before, dirty, verr := m.Version()
	slog.InfoContext(ctx, "applying database migrations",
		"schema.version_before", before)

	// A fresh database (no version yet) holds nothing worth copying, and a
	// dirty one is refused by Up below anyway — the snapshot taken before the
	// migration that left it dirty is the one to restore.
	if snapshot != nil && verr == nil && !dirty {
		if _, err := src.Next(before); err == nil {
			if err := snapshot(ctx, before); err != nil {
				return err
			}
		}
	}

	// Atlas opens every table-rebuild migration with `PRAGMA foreign_keys =
	// off`, and golang-migrate runs each file inside a transaction, where that
	// pragma is a documented no-op. The DSN turns foreign keys on, so the
	// implicit delete behind `DROP TABLE movies` ran with cascades live and
	// took every season, episode, media file, event and download record with
	// it. Disabling it out here holds because the pool is capped at one
	// connection, so the setting is still in force inside those transactions.
	var foreignKeys int
	if err := db.QueryRowContext(ctx, "PRAGMA foreign_keys").
		Scan(&foreignKeys); err != nil {
		return fmt.Errorf("read foreign keys: %w", err)
	}
	if _, err := db.ExecContext(ctx, "PRAGMA foreign_keys = off"); err != nil {
		return fmt.Errorf("disable foreign keys: %w", err)
	}

	started := time.Now()
	err = m.Up()
	elapsed := time.Since(started)
	if err != nil && !errors.Is(err, migrate.ErrNoChange) {
		slog.ErrorContext(ctx, "database migrations failed",
			"schema.version_before", before,
			"duration_ms", elapsed.Milliseconds(),
			"error", err)
		return fmt.Errorf("migrate up: %w", err)
	}

	if _, err := db.ExecContext(
		ctx,
		fmt.Sprintf("PRAGMA foreign_keys = %d", foreignKeys),
	); err != nil {
		return fmt.Errorf("restore foreign keys: %w", err)
	}
	// Enforcement was off for the whole run, so a data migration writing a
	// dangling reference now succeeds silently. This is the canary for that.
	var dangling int
	if err := db.QueryRowContext(
		ctx,
		"SELECT count(*) FROM pragma_foreign_key_check",
	).Scan(&dangling); err != nil {
		slog.WarnContext(ctx, "foreign key check failed", "error", err)
	} else if dangling > 0 {
		slog.ErrorContext(ctx, "database holds dangling references after migrating",
			"violations", dangling)
	}

	after, dirty, _ := m.Version()
	slog.InfoContext(ctx, "database migrations applied",
		"schema.version_before", before,
		"schema.version", after,
		"schema.dirty", dirty,
		"duration_ms", elapsed.Milliseconds())
	return nil
}

// LatestSchemaVersion is the newest migration this binary carries: the highest
// schema version it can boot from. A restore refuses a backup above it.
func LatestSchemaVersion() (uint, error) {
	src, err := iofs.New(migrationsFS, "migrations")
	if err != nil {
		return 0, fmt.Errorf("migration source: %w", err)
	}
	defer src.Close()
	v, err := src.First()
	if err != nil {
		return 0, fmt.Errorf("first migration: %w", err)
	}
	for {
		next, err := src.Next(v)
		if errors.Is(err, fs.ErrNotExist) {
			return v, nil
		}
		if err != nil {
			return 0, fmt.Errorf("next migration after %d: %w", v, err)
		}
		v = next
	}
}
